export type YmaReceiptData = {
  title: string;
  subtitle: string;
  receiptNo: string;
  payerName: string;
  accountLabel: string;
  accountValue: string;
  periodLabel: string;
  periodValue: string;
  amount: string;
  paymentMethod: string;
  transactionLabel?: string;
  transactionValue?: string;
  paidOn: string;
};

function escapeHtml(value: string) {
  return String(value ?? '-')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

export function createYmaReceiptHtml(data: YmaReceiptData) {
  const d = {
    title: escapeHtml(data.title),
    subtitle: escapeHtml(data.subtitle),
    receiptNo: escapeHtml(data.receiptNo || '-'),
    payerName: escapeHtml(data.payerName || '-'),
    accountLabel: escapeHtml(data.accountLabel || 'Account No.'),
    accountValue: escapeHtml(data.accountValue || '-'),
    periodLabel: escapeHtml(data.periodLabel || 'Bill Period'),
    periodValue: escapeHtml(data.periodValue || '-'),
    amount: escapeHtml(data.amount || '0.00'),
    paymentMethod: escapeHtml(data.paymentMethod || '-'),
    transactionLabel: escapeHtml(data.transactionLabel || 'UTR / Transaction ID'),
    transactionValue: escapeHtml(data.transactionValue || '-'),
    paidOn: escapeHtml(data.paidOn || '-'),
  };

  const logoDataUri = 'data:image/png;base64,';

  return `<!doctype html>
<html>
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>${d.title} - YMA Salem Branch</title>
<style>
  *{box-sizing:border-box}
  @page{size:A4;margin:18mm 14mm}
  body{margin:0;background:#f3f4f6;color:#171717;font-family:Arial,Helvetica,sans-serif}
  .page{max-width:760px;margin:24px auto;padding:0 16px}
  .receipt{background:#fff;border:1px solid #dedede;border-radius:18px;overflow:hidden;box-shadow:0 8px 28px rgba(0,0,0,.08)}
  .topbar{height:7px;background:linear-gradient(to bottom,#c62828 0 33%,#fff 33% 66%,#111 66% 100%)}
  .header{padding:24px 26px 18px;background:#fff}
  .brand{display:flex;align-items:center;gap:18px}
  .logo{width:92px;height:92px;flex:0 0 auto;display:flex;align-items:center;justify-content:center}
  .logo img{display:block;width:92px;height:92px;object-fit:contain}
  .brand-copy{flex:1}
  .eyebrow{font-size:11px;letter-spacing:2px;font-weight:800;color:#777;margin-bottom:5px}
  .branch{font-size:25px;line-height:1.1;font-weight:900;letter-spacing:.4px}
  .location{margin-top:5px;font-size:12px;color:#666;font-weight:600}
  .doc{margin-top:18px;display:flex;justify-content:space-between;gap:14px;align-items:end}
  .doc-title{font-size:22px;font-weight:900;letter-spacing:.2px}
  .doc-subtitle{font-size:12px;color:#666;margin-top:4px}
  .receipt-chip{border:1px solid #ddd;border-radius:10px;padding:9px 12px;min-width:160px;text-align:right}
  .chip-label{font-size:9px;letter-spacing:1.2px;color:#888;font-weight:800}
  .chip-value{margin-top:4px;font-size:11px;font-weight:900;word-break:break-word}
  .rule{height:1px;background:#e7e7e7;margin:0 26px}
  .body{padding:20px 26px 22px}
  .section-label{font-size:10px;letter-spacing:1.6px;color:#888;font-weight:900;margin-bottom:9px}
  .name{font-size:18px;font-weight:900;margin-bottom:16px}
  .grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  .field{border:1px solid #e7e7e7;border-radius:12px;padding:12px 13px;background:#fafafa}
  .field-label{font-size:9px;letter-spacing:1.1px;color:#888;font-weight:800}
  .field-value{margin-top:5px;font-size:13px;font-weight:800;line-height:1.35;word-break:break-word}
  .amount-box{margin-top:14px;border-radius:14px;padding:16px;background:#171717;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:18px}
  .amount-copy small{display:block;font-size:9px;letter-spacing:1.2px;color:#cfcfcf;font-weight:800}
  .amount-copy strong{display:block;margin-top:4px;font-size:27px;letter-spacing:.2px}
  .paid-badge{border:1px solid rgba(255,255,255,.28);padding:8px 10px;border-radius:999px;font-size:9px;letter-spacing:1.3px;font-weight:900;white-space:nowrap}
  .footer{padding:17px 26px 21px;background:#fafafa;border-top:1px solid #e7e7e7}
  .footer-row{display:flex;justify-content:space-between;gap:18px;align-items:flex-end}
  .footer-note{font-size:10px;color:#666;line-height:1.5;max-width:70%}
  .signature{min-width:150px;text-align:center}
  .sig-line{border-top:1px solid #333;margin-bottom:5px}
  .sig-text{font-size:9px;letter-spacing:1px;font-weight:800;color:#555}
  .mini-brand{margin-top:14px;text-align:center;font-size:9px;letter-spacing:1.6px;font-weight:900;color:#777}
  @media print{
    body{background:#fff}
    .page{margin:0 auto;padding:0}
    .receipt{box-shadow:none;border:1px solid #ccc}
  }
  @media(max-width:620px){
    .grid{grid-template-columns:1fr}
    .doc{flex-direction:column;align-items:stretch}
    .receipt-chip{text-align:left;min-width:0}
    .footer-row{flex-direction:column;align-items:stretch}
    .footer-note{max-width:none}
    .signature{max-width:220px}
  }
</style>
</head>
<body>
  <div class="page">
    <div class="receipt">
      <div class="topbar"></div>
      <div class="header">
        <div class="brand">
          <div class="logo"><img src="${logoDataUri}" alt="Young Mizo Association logo" /></div>
          <div class="brand-copy">
            <div class="eyebrow">YOUNG MIZO ASSOCIATION</div>
            <div class="branch">YMA Salem Branch</div>
            <div class="location">Salem, Mizoram</div>
          </div>
        </div>
        <div class="doc">
          <div>
            <div class="doc-title">${d.title}</div>
            <div class="doc-subtitle">${d.subtitle}</div>
          </div>
          <div class="receipt-chip">
            <div class="chip-label">OFFICIAL RECEIPT</div>
            <div class="chip-value">${d.receiptNo}</div>
          </div>
        </div>
      </div>
      <div class="rule"></div>
      <div class="body">
        <div class="section-label">PAYMENT RECEIVED FROM</div>
        <div class="name">${d.payerName}</div>
        <div class="grid">
          <div class="field"><div class="field-label">${d.accountLabel}</div><div class="field-value">${d.accountValue}</div></div>
          <div class="field"><div class="field-label">${d.periodLabel}</div><div class="field-value">${d.periodValue}</div></div>
          <div class="field"><div class="field-label">PAYMENT METHOD</div><div class="field-value">${d.paymentMethod}</div></div>
          <div class="field"><div class="field-label">${d.transactionLabel}</div><div class="field-value">${d.transactionValue}</div></div>
          <div class="field"><div class="field-label">PAID ON</div><div class="field-value">${d.paidOn}</div></div>
          <div class="field"><div class="field-label">BRANCH</div><div class="field-value">YMA Salem Branch</div></div>
        </div>
        <div class="amount-box">
          <div class="amount-copy"><small>AMOUNT PAID</small><strong>₹${d.amount}</strong></div>
          <div class="paid-badge">PAYMENT VERIFIED</div>
        </div>
      </div>
      <div class="footer">
        <div class="footer-row">
          <div class="footer-note">This receipt confirms that the above payment has been recorded by YMA Salem Branch. Please retain this receipt for your records.</div>
          <div class="signature"><div class="sig-line"></div><div class="sig-text">AUTHORIZED</div></div>
        </div>
        <div class="mini-brand">YMA Salem Branch • COMMUNITY SERVICE</div>
      </div>
    </div>
  </div>
  <script>
    window.onload=function(){setTimeout(function(){window.print()},350)};
  </script>
</body>
</html>`;
}
